/*
 * A348460  a(n) = min(A307720(n), A307720(n+1)).
 * https://oeis.org/A348460
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, look
 * Formula:   a(n) = min(A307720(n), A307720(n+1)); A307720 is generated by
 *            greedy search (lexicographically earliest, exactly k consecutive
 *            pairs with product k)
 * Range:     u8 n <= 25000, u16 n <= 25000, u32 n <= 25000, u64 n <= 25000,
 *            u128 n <= 25000, big any n
 * Validated: standard, pass, 119 terms through n = 9230 (2026-11-10)
 * Helpers:   mem
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include "../utils/mem.h"

static seq_t *A307720_seq = NULL;
static size_t A307720_len = 0;
static size_t A307720_cap = 0;
static seq_t *A307720_cnt = NULL;
static size_t A307720_cnt_cap = 0;

static void A307720_extend(size_t n)
{
    if (A307720_len == 0) {
        A307720_cap = 16;
        A307720_seq = mem_new(seq_t, A307720_cap);
        A307720_seq[0] = (seq_t)1;
        A307720_len = 1;
        A307720_cnt_cap = 16;
        A307720_cnt = mem_new(seq_t, A307720_cnt_cap);
    }
    while (A307720_len < n) {
        seq_t prev = A307720_seq[A307720_len - 1];
        seq_t x = (seq_t)1;
        for (;;) {
            seq_t prod = prev * x;
            size_t pi = (size_t)(long long)prod;
            if (pi >= A307720_cnt_cap) {
                size_t nc = A307720_cnt_cap;
                while (nc <= pi) nc <<= 1;
                A307720_cnt = mem_resize(seq_t, A307720_cnt, nc);
                for (size_t i = A307720_cnt_cap; i < nc; ++i) A307720_cnt[i] = (seq_t)0;
                A307720_cnt_cap = nc;
            }
            if (A307720_cnt[pi] < prod) {
                A307720_cnt[pi]++;
                if (A307720_len >= A307720_cap) {
                    size_t nc = A307720_cap << 1;
                    A307720_seq = mem_resize(seq_t, A307720_seq, nc);
                    for (size_t i = A307720_cap; i < nc; ++i) A307720_seq[i] = (seq_t)0;
                    A307720_cap = nc;
                }
                A307720_seq[A307720_len++] = x;
                break;
            }
            x++;
        }
    }
}

seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;
    A307720_extend((size_t)n + 1);
    seq_t u = A307720_seq[n - 1];
    seq_t v = A307720_seq[n];
    return (u < v) ? u : v;
}
